import{_ as a,o,c as i,a2 as l}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"打包与发布","description":"","frontmatter":{"title":"打包与发布","order":22},"headers":[],"relativePath":"zh/learn/mod/publish.md","filePath":"zh/learn/mod/publish.md","lastUpdated":1786943111000}'),t={name:"zh/learn/mod/publish.md"};function s(r,e,n,d,h,c){return o(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="打包与发布" tabindex="-1">打包与发布 <a class="header-anchor" href="#打包与发布" aria-label="Permalink to &quot;打包与发布&quot;">​</a></h1><p>写完代码后，把你的 Mod 打包发布，让更多玩家用上它。发布前请先阅读<a href="./guidelines">模组开发规范</a>。</p><h2 id="_1-确认-info-json" tabindex="-1">1. 确认 Info.json <a class="header-anchor" href="#_1-确认-info-json" aria-label="Permalink to &quot;1. 确认 Info.json&quot;">​</a></h2><p><code>Info.json</code> 是 UMM 读取的 Mod 信息文件，在<a href="./first-mod">最小实例</a>中已经写好。发布前再次核对 <code>EntryMethod</code>、<code>AssemblyName</code>、<code>Version</code>。</p><h2 id="_2-编译与部署" tabindex="-1">2. 编译与部署 <a class="header-anchor" href="#_2-编译与部署" aria-label="Permalink to &quot;2. 编译与部署&quot;">​</a></h2><p>模板支持自动部署：编译后会把产物放到游戏目录的 Mods 文件夹，可以直接在游戏内测试。</p><p>手动部署时，把编译产物放到：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ADOFAI/Mods/MyFirstMod/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>发布包应包含：</p><ul><li><code>MyFirstMod.dll</code>（编译产物）</li><li><code>Info.json</code></li><li>使用说明（README）</li><li>依赖的其它 DLL（如果有）</li></ul><h2 id="_3-发布到-github-release" tabindex="-1">3. 发布到 GitHub Release <a class="header-anchor" href="#_3-发布到-github-release" aria-label="Permalink to &quot;3. 发布到 GitHub Release&quot;">​</a></h2><ol><li>把代码推送到你的 GitHub 仓库</li><li>在仓库页面创建 <strong>Release</strong></li><li>上传编译好的 DLL 与使用说明</li></ol><blockquote><p>常见坑：玩家误下载「源码压缩包」导致无法加载。发布时务必把编译产物也上传到 Release。</p></blockquote><h2 id="_4-分享到-mod-平台" tabindex="-1">4. 分享到 Mod 平台 <a class="header-anchor" href="#_4-分享到-mod-平台" aria-label="Permalink to &quot;4. 分享到 Mod 平台&quot;">​</a></h2><p>也可以在组织的 Mod 平台 <a href="https://modrift.org" target="_blank" rel="noreferrer">modrift.org</a> 发布，让更多玩家发现你的作品。</p><h2 id="_5-用-github-actions-自动构建" tabindex="-1">5. 用 GitHub Actions 自动构建 <a class="header-anchor" href="#_5-用-github-actions-自动构建" aria-label="Permalink to &quot;5. 用 GitHub Actions 自动构建&quot;">​</a></h2><p>手动编译、打包、上传 Release 很繁琐。可以用 GitHub Actions 在推送时自动完成，详见 <a href="./github-actions">GitHub Actions 自动构建</a>。</p><h2 id="你学到了什么" tabindex="-1">你学到了什么 <a class="header-anchor" href="#你学到了什么" aria-label="Permalink to &quot;你学到了什么&quot;">​</a></h2><ul><li>发布包应包含哪些文件</li><li>通过 GitHub Release 发布 Mod</li><li>自动构建的入口</li></ul><h2 id="系列完成-🎉" tabindex="-1">系列完成 🎉 <a class="header-anchor" href="#系列完成-🎉" aria-label="Permalink to &quot;系列完成 🎉&quot;">​</a></h2><p>你已经走完了 ADOFAI Mod 开发的完整流程。接下来可以：</p><ul><li>探索<a href="./../../libs/">库文档</a>，用代码处理关卡文件</li><li>体验<a href="./../../mods/online-tools/">在线工具</a>，或为<a href="./../../mods/">使用指南</a>补充你的 Mod 教程</li></ul>',22)])])}const b=a(t,[["render",s]]);export{p as __pageData,b as default};
